const createFirmwareRolloutMembers = `-- name: CreateFirmwareRolloutMembers :many
INSERT INTO firmware_rollout_member (
    rollout_id,
    batch_id,
    org_id,
    device_id,
    position,
    model_identity_key,
    model_identity_validated_at,
    source_snapshot,
    target_snapshot,
    revert_snapshot
)
SELECT
    $1,
    batch.id,
    device.org_id,
    device.id,
    (input.value->>'position')::int,
    NULLIF(input.value->>'model_identity_key', ''),
    NULLIF(input.value->>'model_identity_validated_at', '')::timestamptz,
    input.value->'source_snapshot',
    input.value->'target_snapshot',
    input.value->'revert_snapshot'
FROM jsonb_array_elements($2::jsonb) AS input(value)
JOIN firmware_rollout_batch batch
  ON batch.rollout_id = $1
 AND batch.org_id = $3
 AND batch.position = (input.value->>'batch_position')::int
JOIN device
  ON device.device_identifier = input.value->>'device_identifier'
 AND device.org_id = $3
 AND device.deleted_at IS NULL
ORDER BY (input.value->>'position')::int
RETURNING id, rollout_id, batch_id, org_id, device_id, position, state, revision, source_snapshot, target_snapshot, revert_snapshot, enforcement_id, command_batch_uuid, last_error, admitted_at, settled_at, owner_released_at, created_at, updated_at, source_release_set_id, source_release_target_id, target_release_set_id, target_release_target_id, revert_selected_at, model_identity_key, model_identity_validated_at
`

type CreateFirmwareRolloutMembersParams struct {
	RolloutID uuid.UUID
	Members   json.RawMessage
	OrgID     int64
}

func (q *Queries) CreateFirmwareRolloutMembers(ctx context.Context, arg CreateFirmwareRolloutMembersParams) ([]FirmwareRolloutMember, error) {
	rows, err := q.query(ctx, q.createFirmwareRolloutMembersStmt, createFirmwareRolloutMembers, arg.RolloutID, arg.Members, arg.OrgID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []FirmwareRolloutMember
	for rows.Next() {
		var i FirmwareRolloutMember
		if err := rows.Scan(
			&i.ID,
			&i.RolloutID,
			&i.BatchID,
			&i.OrgID,
			&i.DeviceID,
			&i.Position,
			&i.State,
			&i.Revision,
			&i.SourceSnapshot,
			&i.TargetSnapshot,
			&i.RevertSnapshot,
			&i.EnforcementID,
			&i.CommandBatchUuid,
			&i.LastError,
			&i.AdmittedAt,
			&i.SettledAt,
			&i.OwnerReleasedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.SourceReleaseSetID,
			&i.SourceReleaseTargetID,
			&i.TargetReleaseSetID,
			&i.TargetReleaseTargetID,
			&i.RevertSelectedAt,
			&i.ModelIdentityKey,
			&i.ModelIdentityValidatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

